This workshop provides a minimal secure form and server example.

HTML form (index.html):
`html
<!doctype html>
<html>
  <body>
    <form method="post" action="/submit">
      <input name="name" required maxlength="100" />
      <input name="email" type="email" required />
      <input type="hidden" name="csrfToken" value="{{CSRF_TOKEN}}" />
      <button type="submit">Submit</button>
    </form>
  </body>
</html>
`

Express.js server with CSRF check and validation:
``javascript
const express = require('express')
const bodyParser = require('body-parser')
const app = express()
app.use(bodyParser.urlencoded({ extended: false }))

// Simple CSRF token for demo (replace with real library in production)
function generateToken() { return 'demo-token' }

app.get('/', (req, res) => {
  const token = generateToken()
  res.send(`<form method="post" action="/submit"><input name="name" /><input name="email" /><input type="hidden" name="csrfToken" value="${token}" /><button>Submit</button></form>`)
})

app.post('/submit', (req, res) => {
  const { name, email, csrfToken } = req.body
  if (csrfToken !== 'demo-token') return res.status(403).send('Invalid CSRF token')
  if (!name || typeof name !== 'string' || name.length > 100) return res.status(400).send('Invalid name')
  if (!email || !/^\S+@\S+\.\S+$/.test(email)) return res.status(400).send('Invalid email')
  res.send('Form submitted')
})

app.listen(3000)
``

Exercise: run the server locally, submit the form, and then modify the server to use a proper CSRF library and store tokens per session.

Server-side validation is mandatory even when client-side checks exist.

Node.js example (express) validating numeric and string fields:
`javascript
const express = require('express')
const app = express()
app.use(express.json())

app.post('/order', (req, res) => {
  const { quantity, productId } = req.body
  if (!Number.isInteger(quantity) || quantity <= 0) return res.status(400).send('Invalid quantity')
  if (typeof productId !== 'string' || productId.length > 50) return res.status(400).send('Invalid productId')
  // proceed safely
  res.send({ status: 'ok' })
})

app.listen(3000)
`

Python example using simple sanitization:
`python
import re

def sanitize_filename(name):
    # remove directory traversal and unsafe chars
    name = re.sub(r'[^a-zA-Z0-9_.-]', '_', name)
    name = name[:100]
    return name

print(sanitize_filename('../../etc/passwd'))
`

Best practices: whitelist expected formats, normalize inputs, and reject or sanitize unexpected characters.

Example: pseudonymize an identifier before logging and store mapping in a protected store.

Node.js example using a simple hash for pseudonymization:
`javascript
const crypto = require('crypto')

function pseudonymize(id) {
  // use HMAC with a server-side secret (do not hardcode in source)
  const secret = process.env.PSEUDO_SECRET || 'change-me'
  return crypto.createHmac('sha256', secret).update(id).digest('hex')
}

// Usage in request handling
function handleRequest(req, res) {
  const userId = req.body.userId
  const pseudo = pseudonymize(userId)
  // Log pseudonym instead of raw ID
  console.log({ event: 'login', user: pseudo })
  res.send({ status: 'ok' })
}
`

Notes: The secret must be kept securely. Pseudonymization reduces exposure of personal data in logs and analytics while still enabling grouping behavior for debugging or metrics.

